(function(root){
  'use strict';
  const C = root.MistCore;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const date = (value, time = false) => value ? new Date(value).toLocaleString('uk-UA', time ? {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'} : {day:'2-digit',month:'2-digit',year:'numeric'}) : '—';
  const paths = {doc:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z',briefcase:'M3 7h18v13H3z M8 7V3h8v4 M3 12c6 4 12 4 18 0 M12 12v4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L19 6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',close:'M6 6l12 12 M6 18L18 6',download:'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4',school:'M3 9l9-6 9 6 M4 10h16 M6 10v9 M12 10v9 M18 10v9 M3 21h18',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',history:'M3 10a9 9 0 1 1 2 9 M3 4v6h6 M12 7v5l4 2',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 10a9 9 0 1 1 2 9 M3 4v6h6',clip:'M8 12l6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',card:'M2 7a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2z M2 10h20',home:'M3 10l9-7 9 7 M5 10v10h14V10',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20z M2 12h20 M12 2c3 3.5 3 16.5 0 20 M12 2c-3 3.5-3 16.5 0 20'};
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.doc}"/></svg>`;
  const badge = status => {const b=C.STATUSES[status]||[status,'gray'];return `<span class="badge ${b[1]}">${esc(b[0])}</span>`;};
  const button = (text, attrs='', style='secondary', ico='') => `<button class="btn ${style}" ${attrs}>${ico?icon(ico):''}${text}</button>`;
  const empty = (title,text,ico='doc') => `<div class="empty">${icon(ico)}<h3>${title}</h3><p>${text}</p></div>`;
  const foldHint = '<span class="fold-hint" aria-hidden="true"><span class="when-closed">Розгорнути</span><span class="when-open">Згорнути</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg></span>';
  function docActions(d, actor){
    const open = button('Переглянути',`data-doc="${d.id}"`,'secondary small-btn');
    if(d.status==='ready')return open;
    if(actor.role==='student'&&d.status==='requested')return button('Скасувати',`data-action="cancelDocument" data-id="${d.id}"`,'ghost small-btn');
    if(actor.role==='curator'){
      if(d.status==='requested')return button('Взяти в роботу',`data-action="processDocument" data-id="${d.id}"`,'small-btn');
      if(d.status==='processing')return `<div class="actions">${button('Видати',`data-action="issueDocument" data-id="${d.id}"`,'small-btn')}${button('Відхилити',`data-reject="${d.id}"`,'ghost small-btn')}</div>`;
    }
    return `<span class="muted small">${d.status==='rejected'?esc(d.comment):'—'}</span>`;
  }
  function serviceCard(v,kind){
    const svc=C.SERVICES[kind];
    const items=svc.materials.map(m=>`<li class="${m.source==='catalog'?'done':''}">${icon(m.source==='catalog'?'check':'clip')}<div><strong>${esc(m.title)}</strong><p>${esc(m.note)}</p></div></li>`).join('');
    const ready=svc.partner
      ? `<div class="service-certificate"><div class="document-icon">${icon(svc.icon)}</div><div><strong>${esc(svc.partner.name)}</strong><p>${esc(svc.partner.detail)}</p></div></div>`
      : `<div class="service-certificate"><div class="document-icon">${icon('doc')}</div><div><strong>${esc(C.TYPES[kind])}</strong><p>Сформована з демонстраційного обліку · ${esc(v.student.name)} · ${esc(v.student.group)}</p></div></div>`;
    return `<details class="service-card fold-card" id="service-${kind}" data-fold><summary aria-labelledby="${kind}-title"><span class="document-icon">${icon(svc.icon)}</span><h3 id="${kind}-title">${esc(svc.title)}</h3>${foldHint}</summary><div class="fold-body"><p class="service-description">${esc(svc.description)}</p><div class="service-columns"><section><h4>${esc(svc.packTitle)}</h4><ul class="checklist materials-list">${items}</ul></section><section class="service-ready"><h4>${esc(svc.readyHeading)}</h4>${ready}<div class="actions">${button(svc.readyAction,`data-doc="${esc(svc.catalogId)}"`,'secondary','doc')}${button(svc.routeAction,`data-service-route="${kind}"`,'','list')}</div></section></div></div></details>`;
  }
  function serviceCards(v){
    return `<section aria-labelledby="services-title"><div class="section-header"><h2 id="services-title">Студентські сервіси</h2></div><div class="service-grid">${Object.keys(C.SERVICES).map(kind=>serviceCard(v,kind)).join('')}</div></section>`;
  }
  function documents(v){
    const student=v.actor.role==='student', mentor=v.actor.role==='mentor';
    const waiting=v.documents.filter(d=>['requested','processing'].includes(d.status)).length;
    const ready=v.documents.filter(d=>d.status==='ready').length;
    const title=student?'Мої документи':mentor?'Документи студента':'Електронна черга';
    const descriptions={student:'Замовляйте довідки та відстежуйте їхню готовність у своєму кабінеті.',mentor:'Підтвердження, якими студент поділився для дуального навчання.',curator:'Опрацьовуйте звернення та видавайте документи студентам своєї групи.'};
    const cards=[['study','Підтвердження вашого статусу, програми та форми навчання.'],['transcript','Виписка з результатами навчання за освітньою програмою.'],['dual','Погоджені результати роботи та рішення університету.']];
    return `<div class="page-heading"><div><h1>${title}</h1><p>${descriptions[v.actor.role]}</p></div>${student?button('Замовити документ','data-request="study"','','plus'):''}</div>
    <dl class="stats"><div class="stat"><div class="stat-icon">${icon('clock')}</div><div><dd>${waiting}</dd><dt>У роботі</dt></div></div><div class="stat"><div class="stat-icon">${icon('doc')}</div><div><dd>${ready}</dd><dt>Готових документів</dt></div></div><div class="stat status-box"><div class="stat-icon">${icon('shield')}</div><div><dd>Статус підтверджено</dd><dt>Демонстраційний облік · ${esc(v.student.group)}</dt></div></div></dl>
    ${student?`<section aria-labelledby="documents-title"><div class="section-header"><h2 id="documents-title">Доступні документи</h2>${button('Згорнути всі','data-collapse-all','ghost small-btn')}</div><p class="catalog-hint">Натисніть на назву, щоб переглянути деталі та доступні дії.</p><div class="document-grid">${cards.map(([kind,desc])=>`<details class="document-card fold-card ${kind==='dual'?'auto':''}" id="document-${kind}" data-fold><summary aria-labelledby="document-${kind}-title"><span class="document-icon">${icon(kind==='dual'?'briefcase':'doc')}</span><h3 id="document-${kind}-title">${C.TYPES[kind]}</h3>${foldHint}</summary><div class="fold-body"><p>${desc}</p>${kind==='dual'?`<div class="auto-label">${icon('check')}Після завершення навчання</div>`:button('Замовити',`data-request="${kind}"`,'secondary','plus')}</div></details>`).join('')}</div></section>${serviceCards(v)}`:''}
    <div class="section-header"><h2>${student?'Мої запити':mentor?'Спільні документи':'Запити студентів'}</h2><span class="muted small">${v.documents.length} записів</span></div>
    <section class="panel flush">${v.documents.length?`<div class="table-scroll"><table class="request-table" role="table" aria-label="Запити на документи"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Документ</th><th scope="col" role="columnheader">${student?'Призначення':'Студент'}</th><th scope="col" role="columnheader">Статус</th><th scope="col" role="columnheader">Дії</th></tr></thead><tbody role="rowgroup">${v.documents.map(d=>`<tr role="row"><td role="cell" class="doc-row-title" data-label="Документ"><strong>${C.TYPES[d.kind]}</strong><span class="meta">${d.id} · ${date(d.requestedAt)}</span></td><td role="cell" class="break" data-label="${student?'Призначення':'Студент'}">${student?esc(d.purpose):`${esc(d.snapshot.name)}<br><span class="meta">${esc(d.group)}</span>`}</td><td role="cell" data-label="Статус">${badge(d.status)}</td><td role="cell" data-label="Дії">${docActions(d,v.actor)}</td></tr>`).join('')}</tbody></table></div>`:empty(student?'Ваш перший документ — за кілька кроків':mentor?'Документів для перегляду поки немає':'Черга порожня',student?'Оберіть довідку вище. Тут з’явиться запит і кожен наступний статус.':mentor?'Після заявки студента тут з’явиться надане компанії підтвердження.':'Нові звернення студентів з’являться тут автоматично.')}</section>
    ${student?`<div class="notice"><strong>Плануєте дуальне навчання?</strong>Готова довідка про навчання підставиться у вашу заявку до компанії. ${button('Перейти до дуальної освіти','data-page="dual"','ghost','arrow')}</div>`:''}`;
  }
  function outcomes(state,c){
    return `<ol class="outcomes">${C.OUTCOMES.map((o,i)=>{const r=c?state.reports.find(x=>x.caseId===c.id&&x.outcomeId===o.id):null;return `<li class="outcome ${r?.status==='accepted'?'complete':''}"><span class="outcome-num">${r?.status==='accepted'?'✓':i+1}</span><div><strong>${o.title}</strong><p>${o.requirement}</p><span class="small muted">Орієнтовно ${o.hours} год</span>${r?`<div>${badge(r.status)}</div>`:''}</div></li>`;}).join('')}</ol>`;
  }
  function noCase(v,state){
    if(v.actor.role!=='student')return `<section class="panel">${empty('Нових справ поки немає','Заявка з’явиться, коли студент обере компанію та надасть підтвердження навчання.','briefcase')}</section>`;
    const doc=v.documents.find(d=>d.kind==='study'&&d.status==='ready');
    const pending=v.documents.some(d=>d.kind==='study'&&['requested','processing'].includes(d.status));
    return `<div class="dual-layout"><section class="panel"><div class="partner-head"><div class="company-mark">VL</div><div><h2>Vector Lab</h2><p>${esc(v.company.description)}</p></div></div><h3>Розроблення вебзастосунку</h3><p class="partner-description">Отримайте досвід роботи з базою даних, імпортом CSV та перевіркою якості. Наставник підтверджує виконану роботу, куратор оцінює результати за погодженим планом.</p><dl class="detail-grid"><div><dt>Освітня програма</dt><dd>Комп’ютерні науки</dd></div><div><dt>Навчальний обсяг</dt><dd>60 годин · 3 результати</dd></div><div><dt>Наставник компанії</dt><dd>Ірина Мельник</dd></div><div><dt>Куратор університету</dt><dd>Олена Бойко</dd></div></dl><ul class="checklist"><li class="done">${icon('check')}Ваш статус студента підтверджено</li><li class="${doc?'done':''}">${icon(doc?'check':'clock')}${doc?'Довідка готова до додавання у заявку':'Для заявки потрібна готова довідка про навчання'}</li></ul>${doc?button('Подати заявку',`data-apply="${doc.id}"`,'','arrow'):pending?button('Переглянути запит на довідку','data-page="documents"','secondary','arrow'):button('Замовити довідку','data-request="study"','','plus')}</section><section class="panel"><h2>Результати навчання</h2>${outcomes(state,null)}<p class="small muted" style="margin-top:20px">План набуває чинності після погодження компанією та університетом.</p></section></div>`;
  }
  function caseAction(v,c,state){
    if(c.status==='company_review')return v.actor.role==='mentor'?button('Підтвердити участь і план',`data-action="acceptApplication" data-id="${c.id}"`,'','check'):'<p class="muted small">Заявку розглядає наставник компанії.</p>';
    if(c.status==='plan_review')return v.actor.role==='curator'?button('Погодити план навчання',`data-plan="${c.id}"`,'','check'):'<p class="muted small">Компанія підтвердила участь. Очікуємо погодження куратора.</p>';
    if(c.status==='active'&&v.actor.role==='student'){
      const remaining=C.OUTCOMES.filter(o=>!v.reports.some(r=>r.caseId===c.id&&r.outcomeId===o.id));
      return remaining.length?button('Додати проміжний звіт',`data-new-report="${c.id}"`,'','plus'):'<p class="muted small">Усі звіти подано. Їхні статуси — нижче.</p>';
    }
    if(c.status==='active'&&v.actor.role==='curator')return C.completedOutcomes(state,c.id)===3?button('Завершити оцінювання',`data-complete="${c.id}"`,'','check'):'<p class="muted small">Для завершення оцініть усі три результати навчання.</p>';
    return '';
  }
  function reports(v,c){
    const records=v.reports.filter(r=>r.caseId===c.id);
    return records.length?records.map(r=>`<article class="report-card"><div class="report-top"><div><h3>${C.OUTCOMES.find(o=>o.id===r.outcomeId).title}</h3><div class="report-meta"><span>${r.id} · версія ${r.version}</span><span>${r.hours} год</span><span>${date(r.from)}–${date(r.to)}</span></div></div>${badge(r.status)}</div><p class="report-summary">${esc(r.summary)}</p>${['mentor_changes','curator_changes'].includes(r.status)?`<div class="report-comment"><strong>Коментар до доопрацювання:</strong> ${esc(r.comment)}</div>`:''}<div class="report-bottom"><span class="small muted">${r.attachment?`${icon('clip')} ${esc(r.attachment.name)}`:'Структурований звіт'}</span>${v.actor.role==='student'&&['mentor_changes','curator_changes'].includes(r.status)?button('Доопрацювати',`data-edit-report="${r.id}"`,'secondary small-btn'):button((v.actor.role==='mentor'&&r.status==='submitted')||(v.actor.role==='curator'&&r.status==='university_review')?'Переглянути й оцінити':'Переглянути',`data-report="${r.id}"`,'secondary small-btn')}</div></article>`).join(''):empty('Проміжних звітів ще немає',c.status==='active'?'Студент додає опис роботи, години, результат навчання та файл за потреби.':'Звіти стануть доступні після погодження плану.','list');
  }
  function dual(v,state){
    const c=v.cases[0];
    const head=`<div class="page-heading"><div><h1>Дуальна освіта</h1><p>${v.actor.role==='student'?'Від заявки до підтверджених результатів — в одній електронній справі.':v.actor.role==='mentor'?'Підтверджуйте роботу та надавайте студенту зворотний зв’язок.':'Погоджуйте навчальні плани та оцінюйте результати роботи.'}</p></div></div>`;
    if(!c)return head+noCase(v,state);
    const count=C.completedOutcomes(state,c.id), step={company_review:1,plan_review:2,active:3,completed:4}[c.status];
    return head+`<section class="panel"><div class="case-heading"><div><div class="eyebrow">Справа ${c.id}</div><h2>Розроблення вебзастосунку</h2><p class="muted small">${esc(v.student.name)} · ${esc(v.student.group)} · Vector Lab</p></div>${badge(c.status)}</div><ol class="timeline">${['Заявку подано','Компанія','План погоджено','Результати'].map((t,i)=>`<li class="${i<step?'done':''} ${i===step?'current':''}">${t}</li>`).join('')}</ol><div class="actions">${caseAction(v,c,state)}${button('Довідка студента',`data-doc="${c.documentId}"`,'ghost','doc')}</div></section>
    ${c.status==='completed'?`<section class="panel final-card"><h2>Усі результати навчання підтверджено</h2><p class="break">${esc(c.decision)}</p><p class="small">Рішення: ${esc(c.curatorName)} · ${date(c.completedAt)}</p>${v.actor.role!=='mentor'?button('Відкрити електронний підсумок',`data-doc="${v.documents.find(d=>d.caseId===c.id&&d.kind==='dual').id}"`,'','doc'):''}</section>`:''}
    <div class="dual-layout"><section><div class="section-header"><h2>Проміжні звіти</h2><span class="muted small">${v.reports.length} із 3</span></div>${reports(v,c)}</section><section class="panel"><div class="eyebrow">${['active','completed'].includes(c.status)?'Погоджений план':'План навчання'} · v${c.planVersion}</div><h2>Результати навчання</h2><div class="progress-label"><span>Оцінено куратором</span><strong>${count}/3</strong></div><div class="progress-track" role="progressbar" aria-label="Підтверджені результати" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${count}"><span style="width:${count/3*100}%"></span></div>${outcomes(state,c)}<p class="small muted" style="margin-top:20px">Години фіксують обсяг роботи. Рішення приймається після оцінювання результатів навчання.</p></section></div>`;
  }
  function history(v){return `<div class="page-heading"><div><h1>Історія дій</h1><p>Хто, коли та яку версію погодив — від заявки до підсумкового рішення.</p></div></div><section class="panel">${v.events.length?`<ol class="event-list">${v.events.map(e=>`<li><time datetime="${e.at}">${date(e.at,true)}</time><div><strong>${esc(e.actorName)}</strong><p>${esc(e.message)}</p><small>${e.recordId}</small></div></li>`).join('')}</ol>`:empty('Історія почнеться з першої дії','Подайте заявку або замовте документ. Кожне погодження залишить тут запис.','history')}</section>`;}
  function render(state,actorId,page){
    const v=C.view(state,actorId), titles={documents:'Мої документи',dual:'Дуальна освіта',history:'Історія дій'};
    titles.documents=v.actor.role==='curator'?'Електронна черга':v.actor.role==='mentor'?'Документи студента':'Мої документи';
    return `<header class="topbar"><div class="institution">${icon('school')}<div>Навчальний кабінет<small>Концепт модуля Moodle</small></div></div><div class="profile"><span class="avatar" aria-hidden="true">${v.actor.initials}</span><div><strong>${v.actor.name}</strong><small>${v.actor.role==='student'?v.student.group:v.actor.role==='mentor'?'Vector Lab':'Університет'}</small></div></div></header><div class="layout"><aside class="sidebar"><div class="sidebar-heading"><div class="brand"><span class="brand-symbol" aria-hidden="true">М</span><div><span class="brand-name">Міст</span><small>Студентські сервіси</small></div></div><button class="btn secondary nav-toggle" data-nav-toggle aria-expanded="false" aria-controls="cabinet-navigation">${icon('list')}Розділи</button></div><div class="sidebar-content" id="cabinet-navigation"><div class="nav-label">Розділи кабінету</div><nav class="nav" aria-label="Головна навігація">${[['documents','folder',titles.documents],['dual','briefcase','Дуальна освіта'],['history','history','Історія дій']].map(([key,ico,label])=>`<button data-page="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button data-help>${icon('info')}Про прототип</button><button data-reset>${icon('reset')}Почати демо спочатку</button></div></div></aside><div class="workspace"><div class="demo-toolbar"><span class="demo-caption"><span class="demo-tag">ДЕМО</span><span class="demo-explanation">Навчальні дані · у цьому браузері</span></span><div class="role-switch" role="group" aria-label="Роль у демонстрації">${Object.values(C.ACTORS).map(a=>`<button data-role="${a.id}" aria-pressed="${a.id===actorId}">${a.label}</button>`).join('')}</div></div><main id="main" tabindex="-1"><nav class="breadcrumb" aria-label="Поточний розділ"><span>Особистий кабінет</span><span aria-hidden="true">/</span><span>Міст</span><span aria-hidden="true">/</span><span aria-current="page">${titles[page]}</span></nav>${page==='documents'?documents(v):page==='dual'?dual(v,state):history(v)}<footer class="footer-note"><span>Міст · PolyTECH Bootcamp Lviv</span><span>Усі особи, компанія та документи — демонстраційні</span></footer></main></div></div>`;
  }
  root.MistViews={esc,date,icon,badge,button,render,outcomes};
})(globalThis);
